import React, { useState } from 'react';
import { SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, TOP_HEADER_PX } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';

// ─── Brand tokens ─────────────────────────────────────────────────────────────
const BLUE    = '#2B3CC1';
const NAVY    = '#0F1875';
const BG      = '#F0F2FF';
const BG2     = '#E5E8FA';
const BORDER  = 'rgba(43,60,193,0.12)';
const INK     = '#1f2124';
const INK2    = '#515962';

// ─── Sample questions ─────────────────────────────────────────────────────────
const SAMPLE_QUESTIONS = [
  { label: 'Units sold by channel',       query: 'units sold by channel' },
  { label: 'Top performing categories',   query: 'top categories by net revenue' },
  { label: 'Inventory by brand',          query: 'quantity on hand by brand' },
  { label: 'Revenue vs last month',       query: 'net revenue this month vs last month' },
  { label: 'Sell-through rate by category', query: 'sell through rate by category' },
  { label: 'Which products need restocking?', query: 'products with low stock and high sell through rate' },
];

// ─── Gem icon (Lumira mark) ───────────────────────────────────────────────────
function LumiraGem({ size = 48 }: { size?: number }) {
  const s = size;
  const cx = s / 2;
  const cy = s / 2;
  const r = s * 0.42;
  // hexagon points
  const pts = Array.from({ length: 6 }, (_, i) => {
    const angle = (Math.PI / 3) * i - Math.PI / 2;
    return [cx + r * Math.cos(angle), cy + r * Math.sin(angle)];
  });
  const hex = pts.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const top = pts.slice(0, 3);
  const topPoly = [...top, [cx, cy]].map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');

  return (
    <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`} fill="none">
      <polygon points={hex} stroke={BLUE} strokeWidth="2" fill="rgba(43,60,193,0.08)" strokeLinejoin="round" />
      <polygon points={topPoly} fill="rgba(43,60,193,0.18)" strokeLinejoin="round" />
      <line x1={pts[0][0]} y1={pts[0][1]} x2={cx} y2={cy} stroke={BLUE} strokeWidth="1.2" strokeOpacity="0.6" />
      <line x1={pts[1][0]} y1={pts[1][1]} x2={cx} y2={cy} stroke={BLUE} strokeWidth="1.2" strokeOpacity="0.6" />
      <line x1={pts[2][0]} y1={pts[2][1]} x2={cx} y2={cy} stroke={BLUE} strokeWidth="1.2" strokeOpacity="0.6" />
      <line x1={pts[0][0]} y1={pts[0][1]} x2={pts[2][0]} y2={pts[2][1]} stroke={BLUE} strokeWidth="1.2" strokeOpacity="0.4" />
    </svg>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function AskLumiraPage() {
  const { hiddenActions, disabledActions } = useTier();
  const [activeQuery, setActiveQuery] = useState<string | undefined>(undefined);
  const [embedKey, setEmbedKey] = useState(0);

  const handleChip = (query: string) => {
    setActiveQuery(query);
    setEmbedKey(k => k + 1); // force remount with new query
  };

  const PAGE_H = `calc(100vh - ${TOP_HEADER_PX}px)`;

  return (
    <div style={{
      display: 'flex',
      height: PAGE_H,
      backgroundColor: BG,
      overflow: 'hidden',
    }}>

      {/* ── Left: hero panel ───────────────────────────────────────────────── */}
      <div style={{
        flex: '0 0 55%',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        padding: '3rem 4rem',
        borderRight: `1px solid ${BORDER}`,
        textAlign: 'center',
        position: 'relative',
        overflow: 'hidden',
      }}>

        {/* Decorative rings */}
        {[280, 420, 560].map(d => (
          <div key={d} style={{
            position: 'absolute',
            width: d, height: d,
            borderRadius: '50%',
            border: `1px solid rgba(43,60,193,${0.06 - d * 0.00008})`,
            top: '50%', left: '50%',
            transform: 'translate(-50%, -50%)',
            pointerEvents: 'none',
          }} />
        ))}

        {/* Content */}
        <div style={{ position: 'relative', zIndex: 1, maxWidth: 480 }}>

          {/* Gem mark */}
          <div style={{ marginBottom: '1.5rem', display: 'flex', justifyContent: 'center' }}>
            <LumiraGem size={64} />
          </div>

          {/* Powered-by badge */}
          <div style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 6,
            backgroundColor: BLUE,
            color: '#FFFFFF',
            borderRadius: 20,
            padding: '4px 14px',
            fontSize: 10.5,
            fontWeight: 700,
            letterSpacing: '0.08em',
            textTransform: 'uppercase',
            marginBottom: '1.25rem',
          }}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor">
              <path d="M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 17l-6.2 4.3 2.4-7.4L2 9.4h7.6z"/>
            </svg>
            Powered by Lumira AI
          </div>

          {/* Heading */}
          <h1 style={{
            fontSize: 'clamp(28px, 3vw, 40px)',
            fontWeight: 800,
            color: NAVY,
            letterSpacing: '-0.03em',
            margin: '0 0 1rem',
            lineHeight: 1.1,
          }}>
            Ask Lumira
          </h1>

          {/* Description */}
          <p style={{
            fontSize: 14.5,
            color: INK2,
            lineHeight: 1.7,
            margin: '0 0 2rem',
            maxWidth: 400,
          }}>
            Ask anything about your sales, inventory, channels, and suppliers.
            Answers come straight from your live data with interactive charts
            you can drill into — or ask a general question about Lumira.
          </p>

          {/* Sample question chips */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
            {SAMPLE_QUESTIONS.map(q => (
              <button
                key={q.query}
                type="button"
                onClick={() => handleChip(q.query)}
                style={{
                  padding: '7px 14px',
                  borderRadius: 20,
                  border: `1px solid ${BORDER}`,
                  backgroundColor: activeQuery === q.query ? BLUE : '#FFFFFF',
                  color: activeQuery === q.query ? '#FFFFFF' : NAVY,
                  fontSize: 12.5,
                  fontWeight: activeQuery === q.query ? 600 : 500,
                  cursor: 'pointer',
                  letterSpacing: '-0.01em',
                  transition: 'all 0.15s ease',
                  boxShadow: '0 1px 4px rgba(43,60,193,0.06)',
                }}
                onMouseEnter={e => {
                  if (activeQuery !== q.query)
                    (e.currentTarget as HTMLButtonElement).style.backgroundColor = BG2;
                }}
                onMouseLeave={e => {
                  if (activeQuery !== q.query)
                    (e.currentTarget as HTMLButtonElement).style.backgroundColor = '#FFFFFF';
                }}
              >
                {q.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* ── Right: Spotter chat panel ───────────────────────────────────────── */}
      <div style={{
        flex: '0 0 45%',
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#FFFFFF',
        position: 'relative',
        overflow: 'hidden',
      }}>
        {/* Panel header */}
        <div style={{
          padding: '1rem 1.5rem',
          borderBottom: `1px solid ${BORDER}`,
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          flexShrink: 0,
          backgroundColor: '#FFFFFF',
        }}>
          <LumiraGem size={28} />
          <div>
            <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>Lumira AI</div>
            <div style={{ fontSize: 11, color: INK2 }}>Commerce intelligence · ask anything</div>
          </div>
          <div style={{
            marginLeft: 'auto',
            width: 8, height: 8,
            borderRadius: '50%',
            backgroundColor: '#16a34a',
            boxShadow: '0 0 0 3px rgba(22,163,74,0.20)',
          }} />
        </div>

        {/* Spotter embed */}
        <div style={{ flex: 1, overflow: 'hidden', position: 'relative' }}>
          <SpotterEmbed
            key={`ask-lumira-${embedKey}`}
            worksheetId={THOUGHTSPOT_MODEL_ID}
            updatedSpotterChatPrompt
            hideSourceSelection
            hideSampleQuestions={!activeQuery}
            spotterSidebarConfig={{ enablePastConversationsSidebar: true }}
            spotterChatConfig={{
              hideToolResponseCardBranding: true,
              toolResponseCardBrandingLabel: 'Lumira AI',
            }}
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            {...(activeQuery ? { searchOptions: { searchQuery: activeQuery } } : {})}
            style={{ width: '100%', height: '100%', border: 'none', display: 'block' }}
          />
        </div>
      </div>
    </div>
  );
}
